using FullWorth.Backend.Data;
using FullWorth.Backend.Modules.Audit;
using FullWorth.Backend.Security;
using Microsoft.EntityFrameworkCore;

namespace FullWorth.Backend.Modules.Parity;

public sealed record PortfolioWrite(string Name,string Currency,Guid? AccountId,Guid? BenchmarkSecurityId,bool IsArchived=false);
public sealed record SecurityWrite(string Name,string? Isin,string? Wkn,string? Ticker,string AssetType,string Currency,string? Exchange);
public sealed record TradeWrite(Guid? SecurityId,string TradeType,DateOnly TradeDate,decimal? Quantity,decimal? Price,decimal Amount,string Currency,decimal Fees=0,decimal Taxes=0,string? ExternalKey=null,string? Notes=null);
public sealed record PriceWrite(Guid SecurityId,DateOnly PriceDate,decimal Price,string Currency,string Source="manual");
public sealed record WatchlistWrite(string Name);
public sealed record WatchlistItemWrite(Guid SecurityId,decimal? TargetPrice,string? Notes);

public static class InvestmentParityEndpoints
{
    public static IEndpointRouteBuilder MapInvestmentParityEndpoints(this IEndpointRouteBuilder app)
    {
        var p=app.MapGroup("/api/investments").WithTags("Investments");
        p.MapGet("/portfolios",ListPortfolios);p.MapPost("/portfolios",CreatePortfolio);p.MapPut("/portfolios/{id:guid}",UpdatePortfolio);p.MapDelete("/portfolios/{id:guid}",ArchivePortfolio);
        p.MapGet("/securities",ListSecurities);p.MapPost("/securities",CreateSecurity);p.MapPut("/securities/{id:guid}",UpdateSecurity);
        p.MapGet("/portfolios/{portfolioId:guid}/trades",ListTrades);p.MapPost("/portfolios/{portfolioId:guid}/trades",CreateTrade);p.MapPut("/portfolios/{portfolioId:guid}/trades/{id:guid}",UpdateTrade);p.MapDelete("/portfolios/{portfolioId:guid}/trades/{id:guid}",DeleteTrade);
        p.MapPut("/prices",PutPrice);p.MapGet("/portfolios/{portfolioId:guid}/positions",Positions);p.MapGet("/portfolios/{portfolioId:guid}/performance",Performance);p.MapGet("/portfolios/{portfolioId:guid}/dividends",Dividends);
        p.MapGet("/watchlists",ListWatchlists);p.MapPost("/watchlists",CreateWatchlist);p.MapPut("/watchlists/{id:guid}",UpdateWatchlist);p.MapDelete("/watchlists/{id:guid}",DeleteWatchlist);p.MapPut("/watchlists/{id:guid}/items",PutWatchlistItems);p.MapGet("/watchlists/{id:guid}/items",GetWatchlistItems);
        return app;
    }

    private static async Task<IResult> ListPortfolios(Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await ParitySql.IsMemberAsync(db,uid,fullWorthSpaceId,ct))return Results.NotFound();var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT \"Id\",\"Name\",\"Currency\",\"AccountId\",\"BenchmarkSecurityId\",\"IsArchived\",\"CreatedAt\",\"UpdatedAt\" FROM \"InvestmentPortfolios\" WHERE \"FullWorthSpaceId\"=@s ORDER BY \"IsArchived\",\"Name\"",("@s",fullWorthSpaceId));await using var r=await cmd.ExecuteReaderAsync(ct);var rows=new List<object>();while(await r.ReadAsync(ct))rows.Add(PortfolioRow(r));return Results.Ok(rows);}
    private static Task<IResult> CreatePortfolio(Guid fullWorthSpaceId,PortfolioWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WritePortfolio(Guid.NewGuid(),fullWorthSpaceId,request,currentUser,db,audit,false,ct);
    private static Task<IResult> UpdatePortfolio(Guid id,Guid fullWorthSpaceId,PortfolioWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WritePortfolio(id,fullWorthSpaceId,request,currentUser,db,audit,true,ct);
    private static async Task<IResult> WritePortfolio(Guid id,Guid space,PortfolioWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,bool update,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await CanManageInvestments(db,uid,space,ct))return Results.StatusCode(403);if(string.IsNullOrWhiteSpace(request.Name)||request.Currency.Trim().Length!=3)return Results.BadRequest();if(request.AccountId.HasValue){var visible=await ParitySql.VisibleAccountIdsAsync(db,uid,space,ct);if(!visible.Contains(request.AccountId.Value))return Results.BadRequest(new{error="Portfolio account is inaccessible."});}if(request.BenchmarkSecurityId.HasValue&&!await SecurityExists(db,space,request.BenchmarkSecurityId.Value,ct))return Results.BadRequest(new{error="Benchmark security is invalid."});var c=await ParitySql.OpenAsync(db,ct);var now=DateTimeOffset.UtcNow;await using var cmd=update?ParitySql.Command(c,"UPDATE \"InvestmentPortfolios\" SET \"Name\"=@name,\"Currency\"=@currency,\"AccountId\"=@account,\"BenchmarkSecurityId\"=@benchmark,\"IsArchived\"=@archived,\"UpdatedAt\"=@now WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@space",("@name",request.Name.Trim()),("@currency",request.Currency.Trim().ToUpperInvariant()),("@account",request.AccountId),("@benchmark",request.BenchmarkSecurityId),("@archived",request.IsArchived),("@now",now),("@id",id),("@space",space)):ParitySql.Command(c,"INSERT INTO \"InvestmentPortfolios\" (\"Id\",\"FullWorthSpaceId\",\"Name\",\"Currency\",\"AccountId\",\"BenchmarkSecurityId\",\"IsArchived\",\"CreatedAt\",\"UpdatedAt\") VALUES (@id,@space,@name,@currency,@account,@benchmark,@archived,@now,@now)",("@id",id),("@space",space),("@name",request.Name.Trim()),("@currency",request.Currency.Trim().ToUpperInvariant()),("@account",request.AccountId),("@benchmark",request.BenchmarkSecurityId),("@archived",request.IsArchived),("@now",now));if(await cmd.ExecuteNonQueryAsync(ct)==0)return Results.NotFound();audit.Record(space,uid,update?"investment.portfolio.updated":"investment.portfolio.created","InvestmentPortfolio",id);await db.SaveChangesAsync(ct);return Results.Ok(new{id});}
    private static async Task<IResult> ArchivePortfolio(Guid id,Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await PortfolioWritable(db,uid,fullWorthSpaceId,id,ct))return Results.StatusCode(403);var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"UPDATE \"InvestmentPortfolios\" SET \"IsArchived\"=true,\"UpdatedAt\"=@now WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@space",("@now",DateTimeOffset.UtcNow),("@id",id),("@space",fullWorthSpaceId));if(await cmd.ExecuteNonQueryAsync(ct)==0)return Results.NotFound();audit.Record(fullWorthSpaceId,uid,"investment.portfolio.archived","InvestmentPortfolio",id);await db.SaveChangesAsync(ct);return Results.NoContent();}

    private static async Task<IResult> ListSecurities(Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await ParitySql.IsMemberAsync(db,uid,fullWorthSpaceId,ct))return Results.NotFound();var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT \"Id\",\"Name\",\"Isin\",\"Wkn\",\"Ticker\",\"AssetType\",\"Currency\",\"Exchange\" FROM \"Securities\" WHERE \"FullWorthSpaceId\"=@s ORDER BY \"Name\"",("@s",fullWorthSpaceId));await using var r=await cmd.ExecuteReaderAsync(ct);var rows=new List<object>();while(await r.ReadAsync(ct))rows.Add(SecurityRow(r));return Results.Ok(rows);}
    private static Task<IResult> CreateSecurity(Guid fullWorthSpaceId,SecurityWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WriteSecurity(Guid.NewGuid(),fullWorthSpaceId,request,currentUser,db,audit,false,ct);
    private static Task<IResult> UpdateSecurity(Guid id,Guid fullWorthSpaceId,SecurityWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WriteSecurity(id,fullWorthSpaceId,request,currentUser,db,audit,true,ct);
    private static async Task<IResult> WriteSecurity(Guid id,Guid space,SecurityWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,bool update,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await CanManageInvestments(db,uid,space,ct))return Results.StatusCode(403);if(string.IsNullOrWhiteSpace(request.Name)||request.Currency.Trim().Length!=3)return Results.BadRequest();var type=NormalizeAssetType(request.AssetType);var c=await ParitySql.OpenAsync(db,ct);var now=DateTimeOffset.UtcNow;await using var cmd=update?ParitySql.Command(c,"UPDATE \"Securities\" SET \"Name\"=@name,\"Isin\"=@isin,\"Wkn\"=@wkn,\"Ticker\"=@ticker,\"AssetType\"=@type,\"Currency\"=@currency,\"Exchange\"=@exchange,\"UpdatedAt\"=@now WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@space",("@name",request.Name.Trim()),("@isin",request.Isin?.Trim().ToUpperInvariant()),("@wkn",request.Wkn?.Trim().ToUpperInvariant()),("@ticker",request.Ticker?.Trim().ToUpperInvariant()),("@type",type),("@currency",request.Currency.Trim().ToUpperInvariant()),("@exchange",request.Exchange?.Trim()),("@now",now),("@id",id),("@space",space)):ParitySql.Command(c,"INSERT INTO \"Securities\" (\"Id\",\"FullWorthSpaceId\",\"Name\",\"Isin\",\"Wkn\",\"Ticker\",\"AssetType\",\"Currency\",\"Exchange\",\"CreatedAt\",\"UpdatedAt\") VALUES (@id,@space,@name,@isin,@wkn,@ticker,@type,@currency,@exchange,@now,@now)",("@id",id),("@space",space),("@name",request.Name.Trim()),("@isin",request.Isin?.Trim().ToUpperInvariant()),("@wkn",request.Wkn?.Trim().ToUpperInvariant()),("@ticker",request.Ticker?.Trim().ToUpperInvariant()),("@type",type),("@currency",request.Currency.Trim().ToUpperInvariant()),("@exchange",request.Exchange?.Trim()),("@now",now));try{if(await cmd.ExecuteNonQueryAsync(ct)==0)return Results.NotFound();}catch(Exception){return Results.Conflict(new{error="A security with this ISIN may already exist."});}audit.Record(space,uid,update?"investment.security.updated":"investment.security.created","Security",id);await db.SaveChangesAsync(ct);return Results.Ok(new{id});}

    private static async Task<IResult> ListTrades(Guid portfolioId,Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await PortfolioReadable(db,uid,fullWorthSpaceId,portfolioId,ct))return Results.NotFound();var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT \"Id\",\"SecurityId\",\"TradeType\",\"TradeDate\",\"Quantity\",\"Price\",\"Amount\",\"Currency\",\"Fees\",\"Taxes\",\"ExternalKey\",\"Notes\" FROM \"InvestmentTrades\" WHERE \"PortfolioId\"=@p ORDER BY \"TradeDate\" DESC,\"CreatedAt\" DESC",("@p",portfolioId));await using var r=await cmd.ExecuteReaderAsync(ct);var rows=new List<object>();while(await r.ReadAsync(ct))rows.Add(TradeRow(r));return Results.Ok(rows);}
    private static Task<IResult> CreateTrade(Guid portfolioId,Guid fullWorthSpaceId,TradeWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WriteTrade(Guid.NewGuid(),portfolioId,fullWorthSpaceId,request,currentUser,db,audit,false,ct);
    private static Task<IResult> UpdateTrade(Guid id,Guid portfolioId,Guid fullWorthSpaceId,TradeWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WriteTrade(id,portfolioId,fullWorthSpaceId,request,currentUser,db,audit,true,ct);
    private static async Task<IResult> WriteTrade(Guid id,Guid portfolioId,Guid space,TradeWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,bool update,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await PortfolioWritable(db,uid,space,portfolioId,ct))return Results.StatusCode(403);var type=NormalizeTradeType(request.TradeType);if(request.Amount<0||request.Fees<0||request.Taxes<0||request.Currency.Trim().Length!=3)return Results.BadRequest();if(type is "buy" or "sell"&&(request.SecurityId is null||request.Quantity is null or <=0))return Results.BadRequest(new{error="Buy/sell requires a security and positive quantity."});if(request.SecurityId.HasValue&&!await SecurityExists(db,space,request.SecurityId.Value,ct))return Results.BadRequest(new{error="Security is invalid."});var c=await ParitySql.OpenAsync(db,ct);var now=DateTimeOffset.UtcNow;var parameters=new(string,object?)[]{("@security",request.SecurityId),("@type",type),("@date",request.TradeDate),("@quantity",request.Quantity),("@price",request.Price),("@amount",request.Amount),("@currency",request.Currency.Trim().ToUpperInvariant()),("@fees",request.Fees),("@taxes",request.Taxes),("@external",request.ExternalKey?.Trim()),("@notes",request.Notes?.Trim()),("@now",now),("@id",id),("@portfolio",portfolioId),("@space",space)};await using var cmd=update?ParitySql.Command(c,"UPDATE \"InvestmentTrades\" SET \"SecurityId\"=@security,\"TradeType\"=@type,\"TradeDate\"=@date,\"Quantity\"=@quantity,\"Price\"=@price,\"Amount\"=@amount,\"Currency\"=@currency,\"Fees\"=@fees,\"Taxes\"=@taxes,\"ExternalKey\"=@external,\"Notes\"=@notes,\"UpdatedAt\"=@now WHERE \"Id\"=@id AND \"PortfolioId\"=@portfolio AND \"FullWorthSpaceId\"=@space",parameters):ParitySql.Command(c,"INSERT INTO \"InvestmentTrades\" (\"Id\",\"FullWorthSpaceId\",\"PortfolioId\",\"SecurityId\",\"TradeType\",\"TradeDate\",\"Quantity\",\"Price\",\"Amount\",\"Currency\",\"Fees\",\"Taxes\",\"ExternalKey\",\"Notes\",\"CreatedAt\",\"UpdatedAt\") VALUES (@id,@space,@portfolio,@security,@type,@date,@quantity,@price,@amount,@currency,@fees,@taxes,@external,@notes,@now,@now)",parameters);if(await cmd.ExecuteNonQueryAsync(ct)==0)return Results.NotFound();audit.Record(space,uid,update?"investment.trade.updated":"investment.trade.created","InvestmentTrade",id);await db.SaveChangesAsync(ct);return Results.Ok(new{id});}
    private static async Task<IResult> DeleteTrade(Guid id,Guid portfolioId,Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await PortfolioWritable(db,uid,fullWorthSpaceId,portfolioId,ct))return Results.StatusCode(403);var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"DELETE FROM \"InvestmentTrades\" WHERE \"Id\"=@id AND \"PortfolioId\"=@p AND \"FullWorthSpaceId\"=@space",("@id",id),("@p",portfolioId),("@space",fullWorthSpaceId));if(await cmd.ExecuteNonQueryAsync(ct)==0)return Results.NotFound();audit.Record(fullWorthSpaceId,uid,"investment.trade.deleted","InvestmentTrade",id);await db.SaveChangesAsync(ct);return Results.NoContent();}

    private static async Task<IResult> PutPrice(Guid fullWorthSpaceId,PriceWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await CanManageInvestments(db,uid,fullWorthSpaceId,ct))return Results.StatusCode(403);if(request.Price<=0||request.Currency.Trim().Length!=3||!await SecurityExists(db,fullWorthSpaceId,request.SecurityId,ct))return Results.BadRequest();var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"INSERT INTO \"SecurityPrices\" (\"SecurityId\",\"PriceDate\",\"Price\",\"Currency\",\"Source\",\"CreatedAt\") VALUES (@s,@date,@price,@currency,@source,@now) ON CONFLICT (\"SecurityId\",\"PriceDate\",\"Source\") DO UPDATE SET \"Price\"=EXCLUDED.\"Price\",\"Currency\"=EXCLUDED.\"Currency\"",("@s",request.SecurityId),("@date",request.PriceDate),("@price",request.Price),("@currency",request.Currency.Trim().ToUpperInvariant()),("@source",string.IsNullOrWhiteSpace(request.Source)?"manual":request.Source.Trim()),("@now",DateTimeOffset.UtcNow));await cmd.ExecuteNonQueryAsync(ct);audit.Record(fullWorthSpaceId,uid,"investment.price.updated","Security",request.SecurityId);await db.SaveChangesAsync(ct);return Results.NoContent();}

    private static async Task<IResult> Positions(Guid portfolioId,Guid fullWorthSpaceId,DateOnly? asOf,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await PortfolioReadable(db,uid,fullWorthSpaceId,portfolioId,ct))return Results.NotFound();var day=asOf??DateOnly.FromDateTime(DateTime.UtcNow);var data=await LoadInvestmentData(db,portfolioId,day,ct);var positions=ComputePositions(data.Trades,data.Prices,day,data.Securities);return Results.Ok(new{asOf=day,positions,totalMarketValue=positions.Sum(x=>x.MarketValue),totalCostBasis=positions.Sum(x=>x.CostBasis),unrealizedGain=positions.Sum(x=>x.UnrealizedGain)});}

    private static async Task<IResult> Performance(Guid portfolioId,Guid fullWorthSpaceId,DateOnly? from,DateOnly? to,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await PortfolioReadable(db,uid,fullWorthSpaceId,portfolioId,ct))return Results.NotFound();var end=to??DateOnly.FromDateTime(DateTime.UtcNow);var start=from??end.AddYears(-1);if(start>end)return Results.BadRequest();var data=await LoadInvestmentData(db,portfolioId,end,ct);var dates=data.Prices.Where(x=>x.Date>=start&&x.Date<=end).Select(x=>x.Date).Concat(data.Trades.Where(x=>x.Date>=start&&x.Date<=end).Select(x=>x.Date)).Append(start).Append(end).Distinct().OrderBy(x=>x).ToArray();decimal twr=1m;decimal? previous=null;var points=new List<object>();foreach(var date in dates){var pos=ComputePositions(data.Trades,data.Prices,date,data.Securities);var value=pos.Sum(x=>x.MarketValue);var external=ExternalFlow(data.Trades.Where(x=>x.Date==date));if(previous.HasValue&&previous.Value!=0){var r=(value-external-previous.Value)/previous.Value;twr*=1+r;}points.Add(new{date,value});previous=value;}var terminal=ComputePositions(data.Trades,data.Prices,end,data.Securities).Sum(x=>x.MarketValue);var flows=new List<(DateOnly Date,decimal Amount)>();foreach(var t in data.Trades.Where(x=>x.Date>=start&&x.Date<=end)){if(t.Type=="deposit")flows.Add((t.Date,-t.Amount));else if(t.Type=="withdrawal")flows.Add((t.Date,t.Amount));}if(terminal>0)flows.Add((end,terminal));var xirr=Xirr(flows);decimal? benchmark=null;if(data.BenchmarkSecurityId.HasValue){var bp=data.Prices.Where(x=>x.SecurityId==data.BenchmarkSecurityId.Value&&x.Date>=start&&x.Date<=end).OrderBy(x=>x.Date).ToArray();if(bp.Length>=2&&bp[0].Price!=0)benchmark=bp[^1].Price/bp[0].Price-1;}
        return Results.Ok(new{from=start,to=end,twr=dates.Length>1?twr-1:(decimal?)null,xirr,benchmarkReturn=benchmark,marketValue=terminal,points});}

    private static async Task<IResult> Dividends(Guid portfolioId,Guid fullWorthSpaceId,int? year,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await PortfolioReadable(db,uid,fullWorthSpaceId,portfolioId,ct))return Results.NotFound();var c=await ParitySql.OpenAsync(db,ct);var sql="SELECT t.\"Id\",t.\"SecurityId\",t.\"TradeDate\",t.\"Amount\",t.\"Currency\",t.\"Taxes\",s.\"Name\" FROM \"InvestmentTrades\" t LEFT JOIN \"Securities\" s ON s.\"Id\"=t.\"SecurityId\" WHERE t.\"PortfolioId\"=@p AND t.\"TradeType\"='dividend'"+(year.HasValue?" AND EXTRACT(YEAR FROM t.\"TradeDate\")=@year":"")+" ORDER BY t.\"TradeDate\" DESC";await using var cmd=year.HasValue?ParitySql.Command(c,sql,("@p",portfolioId),("@year",year.Value)):ParitySql.Command(c,sql,("@p",portfolioId));await using var r=await cmd.ExecuteReaderAsync(ct);var rows=new List<object>();decimal total=0;while(await r.ReadAsync(ct)){var amount=ParitySql.Decimal(r,"Amount");total+=amount;rows.Add(new{id=ParitySql.Guid(r,"Id"),securityId=ParitySql.NullableGuid(r,"SecurityId"),security=ParitySql.NullableString(r,"Name"),date=ParitySql.NullableDate(r,"TradeDate"),amount,currency=ParitySql.String(r,"Currency"),taxes=ParitySql.Decimal(r,"Taxes")});}return Results.Ok(new{total,items=rows});}

    private static async Task<IResult> ListWatchlists(Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await ParitySql.IsMemberAsync(db,uid,fullWorthSpaceId,ct))return Results.NotFound();var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT \"Id\",\"Name\" FROM \"Watchlists\" WHERE \"FullWorthSpaceId\"=@s AND \"OwnerUserId\"=@u ORDER BY \"Name\"",("@s",fullWorthSpaceId),("@u",uid));await using var r=await cmd.ExecuteReaderAsync(ct);var rows=new List<object>();while(await r.ReadAsync(ct))rows.Add(new{id=ParitySql.Guid(r,"Id"),name=ParitySql.String(r,"Name")});return Results.Ok(rows);}
    private static Task<IResult> CreateWatchlist(Guid fullWorthSpaceId,WatchlistWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WriteWatchlist(Guid.NewGuid(),fullWorthSpaceId,request,currentUser,db,audit,false,ct);
    private static Task<IResult> UpdateWatchlist(Guid id,Guid fullWorthSpaceId,WatchlistWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct)=>WriteWatchlist(id,fullWorthSpaceId,request,currentUser,db,audit,true,ct);
    private static async Task<IResult> WriteWatchlist(Guid id,Guid space,WatchlistWrite request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,bool update,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await ParitySql.IsMemberAsync(db,uid,space,ct))return Results.NotFound();if(string.IsNullOrWhiteSpace(request.Name))return Results.BadRequest();var c=await ParitySql.OpenAsync(db,ct);var now=DateTimeOffset.UtcNow;await using var cmd=update?ParitySql.Command(c,"UPDATE \"Watchlists\" SET \"Name\"=@n,\"UpdatedAt\"=@now WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@s AND \"OwnerUserId\"=@u",("@n",request.Name.Trim()),("@now",now),("@id",id),("@s",space),("@u",uid)):ParitySql.Command(c,"INSERT INTO \"Watchlists\" (\"Id\",\"FullWorthSpaceId\",\"OwnerUserId\",\"Name\",\"CreatedAt\",\"UpdatedAt\") VALUES (@id,@s,@u,@n,@now,@now)",("@id",id),("@s",space),("@u",uid),("@n",request.Name.Trim()),("@now",now));if(await cmd.ExecuteNonQueryAsync(ct)==0)return Results.NotFound();audit.Record(space,uid,update?"watchlist.updated":"watchlist.created","Watchlist",id);await db.SaveChangesAsync(ct);return Results.Ok(new{id});}
    private static async Task<IResult> DeleteWatchlist(Guid id,Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct){var uid=currentUser.RequireUserId();var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"DELETE FROM \"Watchlists\" WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@s AND \"OwnerUserId\"=@u",("@id",id),("@s",fullWorthSpaceId),("@u",uid));if(await cmd.ExecuteNonQueryAsync(ct)==0)return Results.NotFound();audit.Record(fullWorthSpaceId,uid,"watchlist.deleted","Watchlist",id);await db.SaveChangesAsync(ct);return Results.NoContent();}
    private static async Task<IResult> PutWatchlistItems(Guid id,Guid fullWorthSpaceId,IReadOnlyList<WatchlistItemWrite> request,CurrentUserContext currentUser,FullWorthDbContext db,AuditService audit,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await OwnWatchlist(db,id,fullWorthSpaceId,uid,ct))return Results.NotFound();if(request.Any(x=>!SecurityExists(db,fullWorthSpaceId,x.SecurityId,ct).GetAwaiter().GetResult()))return Results.BadRequest();var c=await ParitySql.OpenAsync(db,ct);await using var tx=await db.Database.BeginTransactionAsync(ct);await using(var del=ParitySql.Command(c,"DELETE FROM \"WatchlistItems\" WHERE \"WatchlistId\"=@id",("@id",id)))await del.ExecuteNonQueryAsync(ct);foreach(var item in request.DistinctBy(x=>x.SecurityId)){await using var add=ParitySql.Command(c,"INSERT INTO \"WatchlistItems\" (\"WatchlistId\",\"SecurityId\",\"TargetPrice\",\"Notes\") VALUES (@w,@s,@p,@n)",("@w",id),("@s",item.SecurityId),("@p",item.TargetPrice),("@n",item.Notes?.Trim()));await add.ExecuteNonQueryAsync(ct);}audit.Record(fullWorthSpaceId,uid,"watchlist.items.updated","Watchlist",id);await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Results.NoContent();}
    private static async Task<IResult> GetWatchlistItems(Guid id,Guid fullWorthSpaceId,CurrentUserContext currentUser,FullWorthDbContext db,CancellationToken ct){var uid=currentUser.RequireUserId();if(!await OwnWatchlist(db,id,fullWorthSpaceId,uid,ct))return Results.NotFound();var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"""
SELECT i."SecurityId",s."Name",s."Ticker",s."AssetType",i."TargetPrice",i."Notes",p."Price",p."PriceDate",p."Currency" FROM "WatchlistItems" i JOIN "Securities" s ON s."Id"=i."SecurityId" LEFT JOIN LATERAL (SELECT "Price","PriceDate","Currency" FROM "SecurityPrices" WHERE "SecurityId"=s."Id" ORDER BY "PriceDate" DESC LIMIT 1) p ON true WHERE i."WatchlistId"=@id ORDER BY s."Name"
""",("@id",id));await using var r=await cmd.ExecuteReaderAsync(ct);var rows=new List<object>();while(await r.ReadAsync(ct))rows.Add(new{securityId=ParitySql.Guid(r,"SecurityId"),name=ParitySql.String(r,"Name"),ticker=ParitySql.NullableString(r,"Ticker"),assetType=ParitySql.String(r,"AssetType"),targetPrice=ParitySql.NullableDecimal(r,"TargetPrice"),notes=ParitySql.NullableString(r,"Notes"),price=ParitySql.NullableDecimal(r,"Price"),priceDate=ParitySql.NullableDate(r,"PriceDate"),currency=ParitySql.NullableString(r,"Currency")});return Results.Ok(rows);}

    private sealed record TradeRowData(Guid Id,Guid? SecurityId,string Type,DateOnly Date,decimal? Quantity,decimal? Price,decimal Amount,string Currency,decimal Fees,decimal Taxes);
    private sealed record PriceRowData(Guid SecurityId,DateOnly Date,decimal Price,string Currency);
    private sealed record SecurityRowData(Guid Id,string Name,string AssetType,string Currency);
    private sealed record InvestmentData(List<TradeRowData> Trades,List<PriceRowData> Prices,Dictionary<Guid,SecurityRowData> Securities,Guid? BenchmarkSecurityId);
    private sealed record PositionView(Guid SecurityId,string Name,string AssetType,decimal Quantity,decimal LastPrice,string Currency,decimal MarketValue,decimal CostBasis,decimal UnrealizedGain,decimal? UnrealizedPercent);
    private static async Task<InvestmentData> LoadInvestmentData(FullWorthDbContext db,Guid portfolio,DateOnly asOf,CancellationToken ct){var c=await ParitySql.OpenAsync(db,ct);var trades=new List<TradeRowData>();await using(var cmd=ParitySql.Command(c,"SELECT \"Id\",\"SecurityId\",\"TradeType\",\"TradeDate\",\"Quantity\",\"Price\",\"Amount\",\"Currency\",\"Fees\",\"Taxes\" FROM \"InvestmentTrades\" WHERE \"PortfolioId\"=@p AND \"TradeDate\"<=@date ORDER BY \"TradeDate\",\"CreatedAt\"",("@p",portfolio),("@date",asOf))){await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))trades.Add(new(ParitySql.Guid(r,"Id"),ParitySql.NullableGuid(r,"SecurityId"),ParitySql.String(r,"TradeType"),ParitySql.NullableDate(r,"TradeDate")!.Value,ParitySql.NullableDecimal(r,"Quantity"),ParitySql.NullableDecimal(r,"Price"),ParitySql.Decimal(r,"Amount"),ParitySql.String(r,"Currency"),ParitySql.Decimal(r,"Fees"),ParitySql.Decimal(r,"Taxes")));}var securities=new Dictionary<Guid,SecurityRowData>();await using(var cmd=ParitySql.Command(c,"SELECT \"Id\",\"Name\",\"AssetType\",\"Currency\" FROM \"Securities\" WHERE \"FullWorthSpaceId\"=(SELECT \"FullWorthSpaceId\" FROM \"InvestmentPortfolios\" WHERE \"Id\"=@p)",("@p",portfolio))){await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct)){var row=new SecurityRowData(ParitySql.Guid(r,"Id"),ParitySql.String(r,"Name"),ParitySql.String(r,"AssetType"),ParitySql.String(r,"Currency"));securities[row.Id]=row;}}var prices=new List<PriceRowData>();await using(var cmd=ParitySql.Command(c,"SELECT \"SecurityId\",\"PriceDate\",\"Price\",\"Currency\" FROM \"SecurityPrices\" WHERE \"PriceDate\"<=@date AND \"SecurityId\" IN (SELECT \"Id\" FROM \"Securities\" WHERE \"FullWorthSpaceId\"=(SELECT \"FullWorthSpaceId\" FROM \"InvestmentPortfolios\" WHERE \"Id\"=@p)) ORDER BY \"PriceDate\"",("@date",asOf),("@p",portfolio))){await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))prices.Add(new(ParitySql.Guid(r,"SecurityId"),ParitySql.NullableDate(r,"PriceDate")!.Value,ParitySql.Decimal(r,"Price"),ParitySql.String(r,"Currency")));}Guid? benchmark=null;await using(var cmd=ParitySql.Command(c,"SELECT \"BenchmarkSecurityId\" FROM \"InvestmentPortfolios\" WHERE \"Id\"=@p",("@p",portfolio))){var v=await cmd.ExecuteScalarAsync(ct);benchmark=v is null or DBNull?null:(Guid)v;}return new(trades,prices,securities,benchmark);}
    private static List<PositionView> ComputePositions(List<TradeRowData> trades,List<PriceRowData> prices,DateOnly date,Dictionary<Guid,SecurityRowData> securities){var result=new List<PositionView>();foreach(var group in trades.Where(t=>t.SecurityId.HasValue&&t.Date<=date&&(t.Type=="buy"||t.Type=="sell")).GroupBy(t=>t.SecurityId!.Value)){decimal qty=0,cost=0;foreach(var t in group.OrderBy(x=>x.Date)){if(t.Type=="buy"){qty+=t.Quantity??0;cost+=t.Amount+t.Fees+t.Taxes;}else{var sellQty=t.Quantity??0;var avg=qty==0?0:cost/qty;qty-=sellQty;cost=Math.Max(0,cost-avg*sellQty);}}if(qty<=0)continue;var security=securities[group.Key];var price=prices.Where(p=>p.SecurityId==group.Key&&p.Date<=date).OrderByDescending(p=>p.Date).FirstOrDefault()?.Price??group.Where(t=>t.Price.HasValue).OrderByDescending(t=>t.Date).FirstOrDefault()?.Price??0;var value=qty*price;var gain=value-cost;result.Add(new(group.Key,security.Name,security.AssetType,qty,price,security.Currency,value,cost,gain,cost==0?null:gain/cost));}return result;}
    private static decimal ExternalFlow(IEnumerable<TradeRowData> trades)=>trades.Sum(t=>t.Type switch{"deposit"=>t.Amount,"withdrawal"=>-t.Amount,_=>0});
    private static decimal? Xirr(List<(DateOnly Date,decimal Amount)> flows){if(flows.Count<2||!flows.Any(x=>x.Amount<0)||!flows.Any(x=>x.Amount>0))return null;var first=flows.Min(x=>x.Date);double rate=.1;for(var iter=0;iter<100;iter++){double f=0,df=0;foreach(var flow in flows){var years=(flow.Date.DayNumber-first.DayNumber)/365.0;var denom=Math.Pow(1+rate,years);f+=(double)flow.Amount/denom;if(years!=0)df-=years*(double)flow.Amount/Math.Pow(1+rate,years+1);}if(Math.Abs(f)<1e-7)return(decimal)rate;if(Math.Abs(df)<1e-12)break;var next=rate-f/df;if(next<=-0.9999||double.IsNaN(next)||double.IsInfinity(next))break;if(Math.Abs(next-rate)<1e-9)return(decimal)next;rate=next;}return null;}

