    private static object TradeRow(System.Data.Common.DbDataReader r)=>new{id=ParitySql.Guid(r,"Id"),securityId=ParitySql.NullableGuid(r,"SecurityId"),tradeType=ParitySql.String(r,"TradeType"),tradeDate=ParitySql.NullableDate(r,"TradeDate"),quantity=ParitySql.NullableDecimal(r,"Quantity"),price=ParitySql.NullableDecimal(r,"Price"),amount=ParitySql.Decimal(r,"Amount"),currency=ParitySql.String(r,"Currency"),fees=ParitySql.Decimal(r,"Fees"),taxes=ParitySql.Decimal(r,"Taxes"),externalKey=ParitySql.NullableString(r,"ExternalKey"),notes=ParitySql.NullableString(r,"Notes")};
    private static string NormalizeAssetType(string? v)=>v?.Trim().ToLowerInvariant() switch{"etf"=>"etf","stock"=>"stock","fund"=>"fund","bond"=>"bond","crypto"=>"crypto","metal"=>"metal",_=>"other"};
    private static string NormalizeTradeType(string? v)=>v?.Trim().ToLowerInvariant() switch{"buy"=>"buy","sell"=>"sell","dividend"=>"dividend","interest"=>"interest","fee"=>"fee","tax"=>"tax","deposit"=>"deposit","withdrawal"=>"withdrawal","split"=>"split","transfer"=>"transfer",_=>"other"};
    private static async Task<bool> SecurityExists(FullWorthDbContext db,Guid space,Guid id,CancellationToken ct){var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT 1 FROM \"Securities\" WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@s",("@id",id),("@s",space));return await cmd.ExecuteScalarAsync(ct)is not null;}
    private static async Task<bool> PortfolioReadable(FullWorthDbContext db,Guid uid,Guid space,Guid id,CancellationToken ct){if(!await ParitySql.IsMemberAsync(db,uid,space,ct))return false;var visible=await ParitySql.VisibleAccountIdsAsync(db,uid,space,ct);var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT \"AccountId\" FROM \"InvestmentPortfolios\" WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@s",("@id",id),("@s",space));var value=await cmd.ExecuteScalarAsync(ct);return value switch{null=>false,DBNull=>true,Guid account=>visible.Contains(account),_=>false};}
    private static async Task<bool> PortfolioWritable(FullWorthDbContext db,Guid uid,Guid space,Guid id,CancellationToken ct){if(!await CanManageInvestments(db,uid,space,ct))return false;var writable=await ParitySql.WritableAccountIdsAsync(db,uid,space,ct);var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT \"AccountId\" FROM \"InvestmentPortfolios\" WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@s",("@id",id),("@s",space));var value=await cmd.ExecuteScalarAsync(ct);return value switch{null=>false,DBNull=>true,Guid account=>writable.Contains(account),_=>false};}
    private static Task<bool> CanManageInvestments(FullWorthDbContext db,Guid uid,Guid space,CancellationToken ct)=>PermissionsErgonomicsParityEndpoints.HasCapabilityAsync(db,uid,space,"investments.manage",ct);
    private static async Task<bool> OwnWatchlist(FullWorthDbContext db,Guid id,Guid space,Guid uid,CancellationToken ct){var c=await ParitySql.OpenAsync(db,ct);await using var cmd=ParitySql.Command(c,"SELECT 1 FROM \"Watchlists\" WHERE \"Id\"=@id AND \"FullWorthSpaceId\"=@s AND \"OwnerUserId\"=@u",("@id",id),("@s",space),("@u",uid));return await cmd.ExecuteScalarAsync(ct)is not null;}
